        self.assertEqual(parse_sku("VEG-0042"), ('VEG', 42))
    def test_add_lot(self):
        self.assertEqual(add_lot({}, "VEG-1", 3), 3)
    def test_low_stock(self):
        self.assertEqual(low_stock({"VEG-1": 2, "HRB-4": 9, "FLW-2": 4}), ['FLW-2', 'VEG-1'])

if __name__ == '__main__':
    unittest.main()

